'use strict';
// Public card IDs only; no authenticated account or customer data in this gallery.
const showcaseDesignURL="/showcase-designs.json";
let showcaseDesigns=approvedShowcaseDesigns,showcaseRequest=null;
const beforePortraitHome=homeHTML;
function galleryCard(c,step=2){const p=Loyalty.program(c),member={showcasePreview:true,id:'RJ-PREVIEW01',name:c.cardLanguage==='en'?'Card preview':'معاينة البطاقة',stamps:step,points:p.type==='points'?step*p.pointsPerVisit:0,rewards:0};return cardHTML(c,member,true);}
function portraitMarkup(designs){return '<div class="portrait-space" aria-hidden="true"></div><div class="portrait-deck">'+designs.map((c,i)=>`<figure class="portrait-card" data-index="${i}" tabindex="0" role="button" aria-label="${esc(c.title||c.name||'بطاقة الولاء')}" aria-pressed="${i===1}"><div class="portrait-face">${galleryCard(c)}</div></figure>`).join('')+'</div>';}
homeHTML=function(){const box=document.createElement('div');box.innerHTML=beforePortraitHome();box.querySelectorAll('.gallery-heading,.gallery-hint').forEach(el=>el.remove());const intro=box.querySelector('.hero-copy>p:not(.landing-kicker)');if(intro)intro.textContent='زيارات، خصومات أو نقاط. صمّم بطاقاتك، اربط فروعك وفريقك، وتابع رجعة عملائك من مكان واحد.';const stage=box.querySelector('.media-gallery');if(stage){stage.className='media-gallery portrait-gallery';stage.setAttribute('role','region');stage.setAttribute('aria-label','معرض بطاقات ثلاثي الأبعاد، اسحب أو استخدم الأسهم للتنقل');stage.innerHTML=showcaseDesigns?portraitMarkup(showcaseDesigns):'<div class="portrait-space" aria-hidden="true"></div>';}return box.innerHTML;};
const beforePortraitBind=bindGallery;
bindGallery=function(){
 const stage=document.querySelector('.portrait-gallery');if(!stage)return beforePortraitBind();
 if(!showcaseDesigns){showcaseRequest||=fetch(showcaseDesignURL).then(r=>{if(!r.ok)throw Error('Showcase unavailable');return r.json();}).then(data=>{if(!Array.isArray(data)||data.length<1)throw Error('Invalid showcase');showcaseDesigns=data;});showcaseRequest.then(()=>{if(!stage.isConnected)return;stage.innerHTML=portraitMarkup(showcaseDesigns);bindGallery();}).catch(()=>{stage.setAttribute('aria-label','تعذر تحميل معرض البطاقات');showcaseRequest=null;});return;}
 const cards=[...stage.querySelectorAll('.portrait-card')],reduce=matchMedia('(prefers-reduced-motion: reduce)');
 let frame=0,alive=true,index=0,drag=null,tiltX=0,tiltY=0,dragOffset=0;
 stage.tabIndex=0;
 const pricing=document.querySelector('.landing .pricing');
 let width=0,cardWidth=0,spacing=0,pricingTop=0;
 function select(next){index=Math.max(0,Math.min(cards.length-1,next));cards.forEach((card,i)=>{const active=i===index;card.classList.toggle('is-active',active);card.setAttribute('aria-pressed',String(active));card.querySelectorAll('.studio-code,.studio-member').forEach(el=>el.setAttribute('aria-hidden',String(!active)));});}
 function measure(){width=stage.clientWidth;const small=width<640;cardWidth=small?Math.min(172,width*.27):Math.min(278,width*.235);spacing=cardWidth*(small?1.12:1.22);cards.forEach(card=>{card.style.width=cardWidth+'px';const rendered=card.querySelector('.studio-card');rendered.style.width='340px';rendered.style.transform=`scale(${cardWidth/340})`;const bottom=card.querySelector('.studio-bottom'),reward=card.querySelector('.studio-reward');if(bottom&&reward)card.style.setProperty('--peek-offset',Math.max(0,bottom.offsetHeight-reward.offsetHeight)+'px');});if(pricing)pricingTop=pricing.getBoundingClientRect().top+scrollY;schedule();}
 function paint(){frame=0;const rect=stage.getBoundingClientRect(),pop=reduce.matches?0:Math.max(0,Math.min(1,(innerHeight-rect.top)/(innerHeight*.8)));const sway=reduce.matches?0:Math.max(-1,Math.min(1,tiltX+dragOffset));cards.forEach((card,i)=>{const slot=i===0?0:i%2?Math.ceil(i/2):-Math.ceil(i/2);const z=reduce.matches?0:pop*55-Math.abs(slot)*14;card.style.zIndex=String(10-Math.abs(slot));card.style.transform=`translate(-50%,-50%) translate3d(${slot*spacing+sway*16}px,${Math.abs(slot)*8}px,${z}px) rotateX(${reduce.matches?0:-tiltY*2}deg) rotateY(${reduce.matches?0:-slot*12+sway*7}deg)`;});if(pricing){const progress=reduce.matches?1:Math.max(0,Math.min(1,(scrollY+innerHeight-pricingTop)/(innerHeight*.65)));pricing.style.setProperty('--section-rise',(1-progress)*35+'px');pricing.style.setProperty('--section-scale',String(.98+progress*.02));}}
 function schedule(){if(!frame&&alive)frame=requestAnimationFrame(paint);}
 function move(e){const r=stage.getBoundingClientRect();if(drag){dragOffset=Math.max(-.7,Math.min(.7,(e.clientX-drag.x)/Math.max(240,width)));drag.moved ||= Math.abs(e.clientX-drag.x)>8;}else{tiltX=Math.max(-1,Math.min(1,(e.clientX-r.left)/r.width*2-1));tiltY=Math.max(-1,Math.min(1,(e.clientY-r.top)/r.height*2-1));}schedule();}
 function down(e){if(drag||e.isPrimary===false||e.button!==0)return;drag={x:e.clientX,moved:false,card:e.target.closest('.portrait-card')};stage.setPointerCapture(e.pointerId);stage.classList.add('is-dragging');}
 function up(e){if(!drag)return;if(!drag.moved&&drag.card)select(Number(drag.card.dataset.index));drag=null;dragOffset=0;stage.classList.remove('is-dragging');schedule();}
 function cancel(){drag=null;dragOffset=0;tiltX=tiltY=0;stage.classList.remove('is-dragging');schedule();}
 function key(e){if(!['ArrowLeft','ArrowRight','Home','Enter',' '].includes(e.key))return;e.preventDefault();const card=e.target.closest('.portrait-card');select(e.key==='Home'?0:e.key==='ArrowLeft'?(index+cards.length-1)%cards.length:e.key==='ArrowRight'?(index+1)%cards.length:card?Number(card.dataset.index):index);}
 function hover(e){if(drag||e.pointerType==='touch')return;const card=e.target.closest('.portrait-card');if(card)select(Number(card.dataset.index));}
 stage.addEventListener('pointermove',move,{passive:true});stage.addEventListener('pointerdown',down);stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',cancel);stage.addEventListener('pointerleave',()=>{if(!drag){tiltX=tiltY=0;select(0);schedule();}});stage.addEventListener('pointerover',hover);stage.addEventListener('focusin',hover);stage.addEventListener('keydown',key);stage.addEventListener('click',e=>{const card=e.target.closest('.portrait-card');if(card&&!drag)select(Number(card.dataset.index));});
 window.addEventListener('scroll',schedule,{passive:true});const observer=new ResizeObserver(measure);observer.observe(stage);reduce.addEventListener('change',measure);measure();
 let step=2;const animation=setInterval(()=>{if(document.hidden||reduce.matches||drag)return;const r=stage.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;step=(step+1)%5;cards.forEach((card,i)=>{card.dataset.demoStep=String(step);const fresh=document.createElement('div');fresh.innerHTML=galleryCard(showcaseDesigns[i],step);card.querySelectorAll('.studio-stamp').forEach((stamp,n)=>{const next=fresh.querySelectorAll('.studio-stamp')[n],earned=next.classList.contains('earned');stamp.classList.toggle('earned',earned);stamp.title=next.title;const img=stamp.querySelector('img'),nextImg=next.querySelector('img');if(img&&nextImg&&img.getAttribute('src')!==nextImg.getAttribute('src')){img.src=nextImg.getAttribute('src');img.alt=nextImg.alt;stamp.classList.remove('demo-changing');void stamp.offsetWidth;stamp.classList.add('demo-changing');}});for(const selector of ['.studio-balance','.studio-points-progress','.studio-reward>span']){const old=card.querySelector(selector),next=fresh.querySelector(selector);if(old&&next)old.innerHTML=next.innerHTML;}const stamps=card.querySelector('.studio-stamps');if(stamps)stamps.setAttribute('aria-label',fresh.querySelector('.studio-stamps').getAttribute('aria-label'));});select(index);paint();},5000);
 stage._cleanup=()=>{alive=false;clearInterval(animation);if(frame)cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',schedule);reduce.removeEventListener('change',measure);};select(index);

};
render();


